def clamp(value, lo, hi):
    """Return `value` limited to the closed interval [lo, hi]."""
    if lo > hi:
        raise ValueError("lo must not be greater than hi")
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value

def test_clamps_high():
    assert clamp(99, 0, 10) == 10


def test_raises_when_lo_greater_than_hi():
    import pytest
    with pytest.raises(ValueError):
        clamp(5, 10, 0)


def test_keeps_type_for_integer_bounds():
    assert type(clamp(5, 0, 10)) is int
    assert type(clamp(-5, 0, 10)) is int
    assert type(clamp(99, 0, 10)) is int
